"""Implementation extracted from the public facade module."""

from __future__ import annotations

from modstore_server.operational_errors import RECOVERABLE_ERRORS
import importlib


def _facade():
    return importlib.import_module("modstore_server.employee_executor")


def _actions_real(
    config: _facade().Dict[str, _facade().Any],
    reasoning: _facade().Dict[str, _facade().Any],
    task: str,
    employee_id: str,
    user_id: int = 0,
) -> _facade().Dict[str, _facade().Any]:
    actions_cfg = _facade()._get_section(config, "actions")
    if employee_id == "taiyangniao-attendance-employee":
        actions_cfg = dict(actions_cfg)
        direct_cfg = dict(actions_cfg.get("direct_python") or {})
        direct_cfg.pop("default_backend_path", None)
        actions_cfg["direct_python"] = direct_cfg
        actions_cfg["handlers"] = ["direct_python"]
    handlers = actions_cfg.get("handlers") or ["echo"]
    requested_handler = str(
        (reasoning.get("input") or {}).get("handler")
        if isinstance(reasoning.get("input"), dict)
        else ""
    ).strip()
    deterministic_council_review = bool(
        employee_id == "change-request-auditor"
        and requested_handler == "direct_python"
        and ("direct_python" in handlers)
    )
    direct_input = reasoning.get("input") if isinstance(reasoning.get("input"), dict) else {}
    reviewed_direct_burn_in = _facade().is_reviewed_direct_burn_in(
        actions_cfg,
        direct_input,
        requested_handler,
        handlers,
        burn_in=_facade()._flag_enabled(direct_input.get("burn_in")),
        read_only=_facade()._flag_enabled(direct_input.get("burn_in_read_only")),
    )
    para_only = bool(
        reasoning.get("skipped_cognition_reason") == "para_first"
        and direct_input.get("_trusted_incident_team_execution") is True
    )
    if para_only:
        handlers = ["para_delegate"]
    elif employee_id in (
        "vibe-coding-maintainer",
        "change-request-auditor",
        "test-qa-runner",
    ) and (not (deterministic_council_review or reviewed_direct_burn_in)):
        handlers = _facade()._prefer_para_with_local_fallback(list(handlers), list(handlers))
    if employee_id == "vibe-coding-maintainer" and not para_only:
        handlers = _facade()._filter_handlers_vibe_coding_maintainer(handlers, reasoning, task)
    outputs: _facade().List[_facade().Dict[str, _facade().Any]] = []
    skip_local_after_para_ok = False
    _LOCAL_FALLBACK_HANDLERS = {
        "agent",
        "vibe_edit",
        "vibe_heal",
        "vibe_code",
        "cursor_delegate",
        "direct_python",
    }
    # 跳过规划 LLM 后 llm_md/echo 只会回显空文本，且台账把 llm_md 视为本地回退，不再产出。
    skip_echo = reasoning.get("skipped_cognition_reason") == "para_first"
    for handler in handlers:
        if (skip_local_after_para_ok or para_only) and str(handler) in _LOCAL_FALLBACK_HANDLERS:
            continue
        if skip_echo and str(handler) in ("llm_md", "echo"):
            continue
        if handler == "echo":
            outputs.append({"handler": "echo", "output": reasoning.get("reasoning", "")})
        elif handler == "http_request":
            http_cfg = actions_cfg.get("http_request") or {}
            url = str(http_cfg.get("url") or "").strip()
            method = str(http_cfg.get("method") or "POST").strip().upper()
            headers = http_cfg.get("headers") or {}
            body_tpl = str(http_cfg.get("body") or "")
            body = body_tpl.replace("{{reasoning}}", str(reasoning.get("reasoning") or ""))
            body = body.replace("{{task}}", task)
            if not url:
                outputs.append({"handler": "http_request", "error": "missing url"})
                continue
            try:
                resp = _facade().httpx.request(
                    method, url, headers=headers, content=body, timeout=30.0
                )
                outputs.append(
                    {
                        "handler": "http_request",
                        "status_code": resp.status_code,
                        "response": resp.text[:2000],
                    }
                )
            except RECOVERABLE_ERRORS as e:
                outputs.append({"handler": "http_request", "error": str(e)})
        elif handler == "webhook":
            webhook_cfg = actions_cfg.get("webhook") or {}
            url = str(webhook_cfg.get("url") or "").strip()
            if not url:
                outputs.append({"handler": "webhook", "error": "missing url"})
                continue
            payload = {
                "employee_id": employee_id,
                "task": task,
                "result": reasoning.get("reasoning", ""),
            }
            try:
                resp = _facade().httpx.post(url, json=payload, timeout=30.0)
                outputs.append({"handler": "webhook", "status_code": resp.status_code})
            except RECOVERABLE_ERRORS as e:
                outputs.append({"handler": "webhook", "error": str(e)})
        elif handler == "data_sync":
            target = str((actions_cfg.get("data_sync") or {}).get("target") or "log")
            if target == "log":
                _facade().logger.info(
                    "[data_sync] employee=%s task=%s result=%s",
                    employee_id,
                    task,
                    str(reasoning.get("reasoning") or "")[:500],
                )
            outputs.append({"handler": "data_sync", "target": target, "status": "ok"})
        elif handler == "direct_python":
            outputs.append(
                _facade()._action_direct_python(actions_cfg, reasoning, task, employee_id, user_id)
            )
        elif handler == "wechat_notify":
            outputs.append(_facade()._action_wechat_notify(actions_cfg, reasoning, task))
        elif handler == "openapi_tool":
            outputs.append(
                _facade()._action_openapi_tool(actions_cfg, reasoning, task, employee_id, user_id)
            )
        elif handler == "fhd_business":
            outputs.append(_facade()._action_fhd_business(actions_cfg, reasoning, task))
        elif handler == "voice_output":
            vo = (
                actions_cfg.get("voice_output")
                if isinstance(actions_cfg.get("voice_output"), dict)
                else {}
            )
            text = str(reasoning.get("reasoning") or "").strip()
            outputs.append(
                {
                    "handler": "voice_output",
                    "status": "pending_tts",
                    "note": "未配置 TTS 服务：返回待合成文本，可由宿主接入阿里云/讯飞/OpenAI TTS",
                    "text_preview": text[:800],
                    "provider": str(vo.get("provider") or "").strip(),
                    "voice_id": str(vo.get("voice_id") or "").strip(),
                }
            )
        elif handler == "agent":
            outputs.append(
                _facade()._action_agent_runner(actions_cfg, reasoning, task, employee_id, user_id)
            )
        elif handler == "para_delegate":
            from modstore_server.para_delegate_handler import dispatch_para_delegate

            cog_in = reasoning.get("input") if isinstance(reasoning.get("input"), dict) else {}
            para_out = dispatch_para_delegate(task=task, input_data=cog_in, employee_id=employee_id)
            outputs.append(para_out)
            if isinstance(para_out, dict) and para_out.get("ok") is True:
                skip_local_after_para_ok = True
        elif handler == "cursor_delegate":
            from modstore_server.cursor_delegate_handler import dispatch_cursor_delegate

            cog_in = reasoning.get("input") if isinstance(reasoning.get("input"), dict) else {}
            outputs.append(
                dispatch_cursor_delegate(task=task, input_data=cog_in, employee_id=employee_id)
            )
        elif handler == "llm_md":
            outputs.append({"handler": "llm_md", "output": reasoning.get("reasoning", "")})
        elif handler == "specialized":
            outputs.append(
                {
                    "handler": "specialized",
                    "ok": True,
                    "output": reasoning.get("reasoning", ""),
                    "note": "specialized handler uses the employee's declared package-specific capability boundary.",
                }
            )
        elif handler in ("vibe_edit", "vibe_heal", "vibe_code"):
            try:
                from modstore_server.integrations.vibe_action_handlers import (
                    dispatch_vibe_handler,
                )

                vibe_out = dispatch_vibe_handler(
                    str(handler), actions_cfg, reasoning, task, employee_id, user_id
                )
            except RECOVERABLE_ERRORS as exc:
                _facade().logger.exception("vibe handler dispatch failed handler=%s", handler)
                vibe_out = {
                    "handler": str(handler),
                    "ok": False,
                    "error": f"dispatch error: {exc}",
                }
            outputs.append(vibe_out or {"handler": str(handler), "ok": False, "error": "no output"})
        elif handler == "doc_sync":
            from modstore_server.integrations.doc_sync_handler import (
                dispatch_doc_sync_handler,
            )

            outputs.append(
                dispatch_doc_sync_handler(actions_cfg, reasoning, task, employee_id, user_id)
            )
        elif handler in ("shell_exec", "ssh_exec"):
            from modstore_server.integrations.ops_action_handlers import (
                dispatch_ops_handler,
            )

            outputs.append(
                dispatch_ops_handler(handler, actions_cfg, reasoning, task, employee_id, user_id)
            )
        else:
            outputs.append({"handler": str(handler), "error": "unknown handler"})
    try:
        _rep_input = reasoning.get("input") if isinstance(reasoning.get("input"), dict) else {}
        _rep_body = ""
        if not _rep_input.get("im_reply_managed"):
            for _o in outputs:
                if not isinstance(_o, dict):
                    continue
                _cand = str(_o.get("answer") or _o.get("summary") or _o.get("output") or "").strip()
                if not _cand:
                    continue
                if _cand[:1] == "{" and '"answer"' in _cand:
                    try:
                        _ans = (_facade().json.loads(_cand) or {}).get("answer")
                        if _ans and str(_ans).strip():
                            _cand = str(_ans).strip()
                    except (ValueError, TypeError):
                        pass
                _rep_body = _cand
                break
        if _rep_body:
            _facade()._emp_im_notify_boss(
                employee_id,
                config if isinstance(config, dict) else {},
                _rep_body,
                "report",
            )
    except RECOVERABLE_ERRORS:
        _facade().logger.debug(
            "actions_real report im hook skipped employee_id=%s",
            employee_id,
            exc_info=True,
        )
    return {
        "task": task,
        "handlers": handlers,
        "outputs": outputs,
        "summary": f"executed {len(outputs)} handlers",
    }


def _extract_token_count(reasoning: _facade().Dict[str, _facade().Any]) -> int:
    raw = reasoning.get("llm_raw") if isinstance(reasoning, dict) else {}
    usage = raw.get("usage") if isinstance(raw, dict) else {}
    total = usage.get("total_tokens")
    if isinstance(total, int):
        return total
    pt = usage.get("prompt_tokens")
    ct = usage.get("completion_tokens")
    return int(pt or 0) + int(ct or 0)

# --- from employee_executor_part06.py ---
"""Implementation extracted from the public facade module."""

from __future__ import annotations

import importlib

from modstore_server.operational_errors import RECOVERABLE_ERRORS


def _facade():
    return importlib.import_module("modstore_server.employee_executor")


def _auto_wrap_execution_result_to_change_requests(
    employee_id: str,
    user_id: int,
    input_payload: _facade().Dict[str, _facade().Any],
    result: _facade().Dict[str, _facade().Any],
) -> _facade().Dict[str, _facade().Any]:
    """Glue layer: execution outputs -> EmployeeChangeRequest.

    Priority:
    1) Respect CR ids already returned by handlers (agent deferred writes).
    2) For outputs carrying ``files_changed`` with ``path + content``, auto-create CR.
    """
    outputs = result.get("outputs") if isinstance(result.get("outputs"), list) else []
    existing_ids: set[int] = set()
    file_candidates: _facade().List[_facade().Dict[str, str]] = []
    top_level_proposed = (
        result.get("proposed_changes") if isinstance(result.get("proposed_changes"), list) else []
    )
    if top_level_proposed:
        synthetic_out = {
            "files_changed": list(top_level_proposed),
            "workspace_root": str(
                input_payload.get("project_root") or input_payload.get("workspace_root") or ""
            ),
        }
        outputs = list(outputs) + [synthetic_out]
    for out in outputs:
        if not isinstance(out, dict):
            continue
        cid_raw = out.get("change_request_id")
        try:
            cid = int(cid_raw or 0)
        except (TypeError, ValueError):
            cid = 0
        if cid > 0:
            existing_ids.add(cid)
        cid_list = (
            out.get("change_request_ids") if isinstance(out.get("change_request_ids"), list) else []
        )
        for one in cid_list:
            try:
                _cid = int(one or 0)
            except (TypeError, ValueError):
                _cid = 0
            if _cid > 0:
                existing_ids.add(_cid)
        files_changed = (
            out.get("files_changed") if isinstance(out.get("files_changed"), list) else []
        )
        proposed = (
            out.get("proposed_changes") if isinstance(out.get("proposed_changes"), list) else []
        )
        if proposed:
            files_changed = list(files_changed) + list(proposed)
        for f in files_changed:
            if isinstance(f, dict):
                path = str(f.get("path") or "").strip()
                content = f.get("content")
                if not isinstance(content, str):
                    content = ""
                ws = str(
                    f.get("workspace_root")
                    or out.get("workspace_root")
                    or input_payload.get("project_root")
                    or input_payload.get("workspace_root")
                    or ""
                ).strip()
                if path:
                    file_candidates.append({"path": path, "content": content, "workspace_root": ws})
            elif isinstance(f, str) and f.strip():
                ws = str(
                    out.get("workspace_root")
                    or input_payload.get("project_root")
                    or input_payload.get("workspace_root")
                    or ""
                ).strip()
                file_candidates.append({"path": f.strip(), "content": "", "workspace_root": ws})
    created_ids: _facade().List[int] = []
    skipped: _facade().List[_facade().Dict[str, str]] = []
    if file_candidates:
        try:
            from modstore_server.employee_change_request_service import (
                defer_write_as_change_request,
            )
            from modstore_server.employee_scope_policy import (
                workspace_policy_from_manifest,
            )

            sf = _facade().get_session_factory()
            with sf() as session:
                try:
                    pack = _facade().load_employee_pack_resolved(session, employee_id)
                except RECOVERABLE_ERRORS:
                    pack = {}
            manifest = pack.get("manifest") if isinstance(pack.get("manifest"), dict) else {}
            scope_globs, forbidden_globs, approval_required_globs = workspace_policy_from_manifest(
                manifest
            )
        except RECOVERABLE_ERRORS as exc:
            return {
                "ok": False,
                "error": f"prepare CR bridge failed: {str(exc)[:300]}",
                "change_request_ids": sorted(existing_ids),
                "existing_change_request_ids": sorted(existing_ids),
                "created_change_request_ids": [],
                "skipped": [{"reason": "prepare_failed"}],
            }
        default_workspace = ""
        try:
            from modstore_server.employee_workspace_manager import get_workspace_path

            default_workspace = str(get_workspace_path(employee_id))
        except RECOVERABLE_ERRORS:
            default_workspace = ""
        dedup_keys: set[str] = set()
        for item in file_candidates:
            path = str(item.get("path") or "").strip()
            content = str(item.get("content") or "")
            ws = str(item.get("workspace_root") or "").strip() or default_workspace
            if not path:
                skipped.append({"reason": "empty_path"})
                continue
            if not content:
                skipped.append({"path": path[:500], "reason": "missing_content"})
                continue
            if not ws:
                skipped.append({"path": path[:500], "reason": "missing_workspace_root"})
                continue
            key = f"{ws}::{path}::{hash(content)}"
            if key in dedup_keys:
                continue
            dedup_keys.add(key)
            try:
                cid = defer_write_as_change_request(
                    employee_id,
                    ws,
                    path,
                    content,
                    scope_globs=scope_globs,
                    forbidden_globs=forbidden_globs,
                    approval_required_globs=approval_required_globs,
                )
                created_ids.append(int(cid))
            except RECOVERABLE_ERRORS as exc:
                skipped.append({"path": path[:500], "reason": str(exc)[:300]})
    all_ids = sorted(existing_ids.union(created_ids))
    return {
        "ok": True,
        "existing_change_request_ids": sorted(existing_ids),
        "created_change_request_ids": created_ids,
        "change_request_ids": all_ids,
        "processed_file_candidates": len(file_candidates),
        "skipped": skipped[:100],
    }


def _handlers_execution_ok(result: _facade().Dict[str, _facade().Any]) -> bool:
    """actions 层：任一 handler 显式成功即通过；否则任一 ok=False 为失败。

    用于 Para 离线后的本地回退：``para_delegate`` 失败但 ``agent``/``vibe_edit``
    成功时不应整单 handler_failed。
    """
    outputs = result.get("outputs") if isinstance(result.get("outputs"), list) else []
    if not outputs:
        return True
    if any((isinstance(out, dict) and out.get("ok") is True for out in outputs)):
        return True
    if any((isinstance(out, dict) and out.get("ok") is False for out in outputs)):
        return False
    return True


def _handler_failure_detail(result: _facade().Dict[str, _facade().Any]) -> str:
    """Return a compact, classifiable description for the first failed handler."""
    outputs = result.get("outputs") if isinstance(result.get("outputs"), list) else []
    for out in outputs:
        if not isinstance(out, dict) or out.get("ok") is not False:
            continue
        parts = []
        for key in ("handler", "status", "source", "error"):
            value = str(out.get(key) or "").strip()
            if value:
                parts.append(f"{key}={value}")
        nested = out.get("output") if isinstance(out.get("output"), dict) else {}
        if nested:
            for key in ("error_code", "error", "summary"):
                value = str(nested.get(key) or "").strip()
                if value:
                    parts.append(f"{key}={value[:240]}")
                    break
        return "handler failed: " + " ".join(parts) if parts else "handler returned ok=False"
    return "one or more handlers returned ok=False"


def _evaluate_employee_risk_gate(
    employee_id: str,
    manifest: _facade().Dict[str, _facade().Any],
    handler_list: _facade().List[str],
    payload: _facade().Dict[str, _facade().Any],
) -> _facade().Dict[str, _facade().Any]:
    try:
        from modstore_server.employee_risk_middleware import gate_action_or_block

        return gate_action_or_block(employee_id, manifest, handler_list, payload)
    except RECOVERABLE_ERRORS as exc:
        _facade().logger.exception("risk middleware unavailable; blocking employee execution")
        return {
            "ok": False,
            "blocked": True,
            "pending_approval": False,
            "risk_level": "blocked",
            "decision": "blocked",
            "reason": "risk middleware unavailable; fail-closed",
            "detail": f"risk middleware error ({type(exc).__name__})",
        }

# --- from employee_executor_part07_phase01.py ---
"""Employee execution transaction phase."""

from __future__ import annotations

import importlib

from modstore_server.employee_executor_part03_part01_part02 import (
    _para_first_skip_cognition,
)
from modstore_server.operational_errors import RECOVERABLE_ERRORS


def _facade():
    return importlib.import_module("modstore_server.employee_executor")


def _execute_employee_phase_01(state):
    state["pack"] = _facade().load_employee_pack_resolved(state["session"], state["employee_id"])
    state["manifest"], burn_in_eligibility = (state["pack"].get("manifest") or {}, {})
    reviewed_contract, reviewed_manifest = _facade()._trusted_system_duty_contract_execution(
        state["employee_id"], state["payload"], user_id=state["user_id"]
    )
    if reviewed_contract and reviewed_manifest:
        state["manifest"] = reviewed_manifest
        state["payload"]["_trusted_duty_contract_execution"] = True
        state["payload"]["work_contract"] = {
            "schema": "xcagi.duty_employee_work_contracts/v1",
            "employee_id": state["employee_id"],
            "mission": str(reviewed_contract.get("mission") or ""),
            "mode": str(reviewed_contract.get("mode") or ""),
            "risk_level": str(reviewed_contract.get("risk_level") or ""),
            "acceptance": list(reviewed_contract.get("acceptance") or []),
        }
    elif _facade()._flag_enabled(state["payload"].get("burn_in")) and _facade()._flag_enabled(
        state["payload"].get("burn_in_read_only")
    ):
        from modstore_server.duty_workforce_burnin import assess_burn_in_eligibility
        from modstore_server.duty_workforce_contracts import (
            load_reviewed_duty_manifest,
            workforce_contract_map,
        )

        state["manifest"] = load_reviewed_duty_manifest(state["employee_id"])
        reviewed_contract = workforce_contract_map().get(state["employee_id"]) or {}
        burn_in_eligibility = assess_burn_in_eligibility(
            state["employee_id"], reviewed_contract, state["manifest"]
        )
        if burn_in_eligibility.get("eligible") is not True:
            raise RuntimeError(
                "duty burn-in eligibility rejected: "
                + str(burn_in_eligibility.get("reason") or "unknown")
            )
        state["payload"]["work_contract"] = {
            "schema": "xcagi.duty_employee_work_contracts/v1",
            "employee_id": state["employee_id"],
            "mission": str(reviewed_contract.get("mission") or ""),
            "mode": str(reviewed_contract.get("mode") or ""),
            "risk_level": str(reviewed_contract.get("risk_level") or ""),
            "acceptance": list(reviewed_contract.get("acceptance") or []),
        }
    state["config"] = _facade().parse_employee_config_v2(state["manifest"])
    try:
        from modstore_server.employee_runtime_policy import apply_policy_to_config

        state["config"], state["runtime_policy"] = apply_policy_to_config(
            state["employee_id"], state["config"]
        )
    except RECOVERABLE_ERRORS:
        _facade().logger.debug(
            "employee runtime policy apply failed employee_id=%s",
            state["employee_id"],
            exc_info=True,
        )
        state["runtime_policy"] = {}
    state["config"] = _facade().bind_reviewed_burn_in_handlers(state["config"], burn_in_eligibility)
    actions_section = state["config"].get("actions") or {}
    actions_inner = (
        actions_section.get("actions")
        if isinstance(actions_section.get("actions"), dict)
        else actions_section
    )
    state["handler_list"] = list((actions_inner or {}).get("handlers") or [])
    gate = _facade()._evaluate_employee_risk_gate(
        state["employee_id"], state["manifest"], state["handler_list"], state["payload"]
    )
    if not gate.get("ok"):
        state["duration_ms"] = round((_facade().time.perf_counter() - state["t0"]) * 1000, 3)
        state["session"].add(
            _facade().EmployeeExecutionMetric(
                user_id=_facade()._resolve_metric_user_id(state["session"], state["user_id"]),
                employee_id=state["employee_id"],
                task=_facade()._metric_task_preview(state["task"]),
                status="blocked_by_risk_gate",
                duration_ms=state["duration_ms"],
                llm_tokens=0,
            )
        )
        state["session"].commit()
        _facade().logger.info(
            "employee_execute_finish employee_id=%s user_id=%s status=blocked_by_risk_gate duration_ms=%s",
            state["employee_id"],
            state["user_id"],
            state["duration_ms"],
        )
        return (
            True,
            {
                "employee_id": state["employee_id"],
                "pack": {"id": state["pack"]["pack_id"], "version": state["pack"]["version"]},
                "duration_ms": state["duration_ms"],
                "result": {
                    "task": state["task"],
                    "handlers": state["handler_list"],
                    "outputs": [],
                    "summary": "blocked by risk middleware",
                    "risk_gate": gate,
                },
                "executed_at": _facade().datetime.now(_facade().timezone.utc).isoformat(),
                "llm_tokens": 0,
                "blocked_by_risk_gate": True,
                "runtime_policy": state["runtime_policy"] or None,
                "risk_level": gate.get("risk_level"),
            },
        )
    ctx = _facade().build_employee_context(state["employee_id"], state["payload"])
    state["perceived"] = _facade()._perception_real(
        state["config"].get("perception", {}), state["payload"], state["session"], state["user_id"]
    )
    try:
        from modstore_server.employee_perception_enricher import enrich_perception

        state["_project_root"] = (
            str(state["payload"].get("project_root") or "").strip()
            if isinstance(state["payload"], dict)
            else ""
        ) or _facade().os.environ.get("MODSTORE_REPO_ROOT", "")
        enrich_perception(
            employee_id=state["employee_id"],
            perceived=state["perceived"] if isinstance(state["perceived"], dict) else {},
            config=state["config"],
            session=state["session"],
            project_root=_facade().Path(state["_project_root"]) if state["_project_root"] else None,
            manifest=state["manifest"] if isinstance(state["manifest"], dict) else None,
        )
    except RECOVERABLE_ERRORS as _pe_exc:
        _facade().logger.debug(
            "perception_enricher failed employee_id=%s err=%s", state["employee_id"], _pe_exc
        )
    try:
        from modstore_server.employee_task_classifier import enrich_perception_with_classification

        enrich_perception_with_classification(
            employee_id=state["employee_id"],
            task=str(state["task"] or ""),
            perceived=state["perceived"] if isinstance(state["perceived"], dict) else {},
        )
    except RECOVERABLE_ERRORS as _tc_exc:
        _facade().logger.debug(
            "task_classifier failed employee_id=%s err=%s", state["employee_id"], _tc_exc
        )
    file_path_fast = (
        isinstance(state["payload"], dict)
        and str(state["payload"].get("file_path") or state["payload"].get("path") or "").strip()
    )
    state["direct_only"] = state["handler_list"] == ["direct_python"] and bool(
        file_path_fast
        or _facade()._deterministic_direct_input_ready(
            actions_inner if isinstance(actions_inner, dict) else {},
            state["payload"] if isinstance(state["payload"], dict) else {},
        )
        or (
            state["employee_id"] == "change-request-auditor"
            and str(state["payload"].get("handler") or "").strip() == "direct_python"
        )
    )
    if state["direct_only"]:
        state["memory"]: _facade().Dict[str, _facade().Any] = {}
        state["reasoning"] = {
            "input": dict(state["payload"]) if isinstance(state["payload"], dict) else {},
            "reasoning": "",
            "skipped_cognition": True,
        }
        state["recovery_meta"] = {}
    elif _para_first_skip_cognition(
        state["employee_id"],
        state["handler_list"],
        state["payload"] if isinstance(state["payload"], dict) else {},
    ):
        state["memory"] = {}
        state["reasoning"] = {
            "input": dict(state["payload"]) if isinstance(state["payload"], dict) else {},
            "reasoning": "",
            "skipped_cognition": True,
            "skipped_cognition_reason": "para_first",
        }
        state["recovery_meta"] = {}
    else:
        state["memory"] = _facade()._memory_real(
            state["config"].get("memory", {}), ctx, state["session"], state["user_id"]
        )
        (
            state["reasoning"],
            state["recovery_meta"],
        ) = _facade()._run_cognition_with_transient_retries(
            state["config"].get("cognition", {}),
            state["perceived"],
            state["memory"],
            state["session"],
            state["user_id"],
            employee_id=state["employee_id"],
            task=state["task"],
            bench_llm_override=state["bench_llm_override"],
        )
    state["reasoning"] = _facade()._merge_original_input_into_reasoning(
        state["reasoning"] if isinstance(state["reasoning"], dict) else {},
        state["payload"] if isinstance(state["payload"], dict) else {},
    )
    return (False, None)

